const https = require('https');
const fs = require('fs');
function connect(keyPath, certPath) {
  const privateKey = fs.readFileSync(keyPath);
  const options = {
    host: 'example.invalid',
    port: 443,
    method: 'GET',
    key: privateKey,
    cert: fs.readFileSync(certPath),
  };
  return https.request(options);
}
module.exports = { connect };

